purpose = 'enroll', seconds = 2.0, count = 5, expected_code = None
@pytest.mark.parametrize("purpose,seconds,count,expected_code", [ ("enroll", 2.0, 5, None), ("identify", 1.5, 2, None), ("enroll", 2.0, 4, "insufficient_speech"), ("enroll", 1.4, 8, "insufficient_speech"), ]) def test_fragmented_pcm_http_preserves_speech_limits(purpose, seconds, count, expected_code): runtime, app, _ = runtime_and_app() spans = [(i * (seconds + 0.4), i * (seconds + 0.4) + seconds) for i in range(count)] rate = 16000 samples = np.zeros(round((spans[-1][1] + 0.4) * rate), dtype=np.float32) for start, end in spans: samples[round(start * rate):round(end * rate)] = 0.1 stream = BytesIO() sf.write(stream, samples, rate, format="WAV", subtype="PCM_16") with TestClient(app) as client: runtime._models.vad = SimpleNamespace(speech_spans=lambda *_: spans) response = client.post( f"/v1/embeddings?purpose={purpose}", headers=HEADERS, content=stream.getvalue() ) if expected_code: assert response.status_code == 422 assert response.json()["detail"]["code"] == expected_code assert "embedding" not in response.json() else: > assert response.status_code == 200 E assert 422 == 200 E + where 422 = <Response [422 Unprocessable Entity]>.status_code
